content.content:
/* ---------- Map / list view switch ---------- */
/* The map and the reachable list are two views of the same shows; only one is
 * mounted at a time, flipped from the right-hand rail. Map is the default. The
 * filters above act on both, so nothing here touches them. */
function applyView(view) {
  state.view = view;
  const mapPane = document.getElementById("map");
  const listPane = document.getElementById("shows");
  if (mapPane) mapPane.hidden = view !== "map";
  if (listPane) listPane.hidden = view !== "list";

  const area = document.querySelector(".view-area");
  if (area) area.dataset.view = view;

  document.querySelectorAll(".view-btn[data-view]").forEach((b) => {
    const on = b.dataset.view === view;
    b.classList.toggle("is-active", on);
    b.setAttribute("aria-pressed", String(on));
  });

  // Leaflet can't measure a display:none container, so a map hidden while the
  // list showed comes back mis-sized — re-measure once it's visible again.
  if (view === "map" && state.map) state.map.invalidateSize();
}

/* Wire the two-position rail (Map | List). Both buttons stay visible so either
 * view is one click away. */
function wireViewSwitch() {
  document.querySelectorAll(".view-btn[data-view]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (state.view === btn.dataset.view) return;
      applyView(btn.dataset.view);
    });
  });
  applyView(state.view); // establish the default (map)
}

/* ---------- Journey strip ---------- */
/* A narrow, always-visible timeline between the filters and the map. It mirrors
 * the journey the map is drawing, left → right:
 *   • origin  — "You are here", now (always shown, styled dull)
 *   • middle  — nothing chosen yet: an animated walker idling in place;
 *               a destination chosen: the leg(s) to it with travel time + slack
 *   • right   — your next commitment, once chosen
 * The slack chip notes how long you'd have before each show starts. */
function renderJourneyStrip() {
--- CSS ---
.plan-time { font-size: 0.74rem; font-weight: 700; color: var(--red-dark); }
.plan-title { font-family: var(--serif); font-weight: 600; font-size: 1.06rem; line-height: 1.18; margin: 1px 0; }
.plan-sub { font-size: 0.78rem; color: var(--muted); }
.plan-slack { display: inline-block; font-size: 0.68rem; font-weight: 700; padding: 3px 9px; border-radius: 999px; }
.plan-slack.ok { color: var(--ok-text); background: var(--ok-bg); }
.plan-slack.late { color: var(--red-dark); background: #fde7e7; }
/* The selected show can't be slipped in before the commitment — a solid, firmer
   red so it's clearly the thing that doesn't work (not the commitment). */
.plan-slack.wontfit { color: #fff; background: #e5484d; }
.plan-buy-inline { display: inline-block; margin-top: 8px; font-size: 0.72rem; font-weight: 700; text-decoration: none; padding: 5px 11px; border-radius: 999px; color: #fff; background: var(--red); }
.plan-buy-inline:hover { background: var(--red-dark); }
.plan-soldout { display: inline-block; margin-top: 8px; font-size: 0.7rem; font-weight: 700; color: var(--muted); }
/* Plan header row: "Your plan" on the left, a mild Maps link on the right. */
.plan-head-row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin: 4px 0 12px; }
.plan-head-row .plan-head { margin: 0; }
.plan-maps-mild { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 5px; font-size: 0.8rem; font-weight: 700; text-decoration: none; color: var(--blue); white-space: nowrap; }
.plan-maps-mild .gmaps-logo { flex: 0 0 auto; }
.plan-maps-mild:hover { text-decoration: underline; }
.plan-maps-mild:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; border-radius: 6px; }

/* Spare-time CTA: turns the plan's slack into a prompt to browse shows. */
/* Spare-time prompt — rendered in the plan's middle slot (see spareCtaNode).
   Visually identical to the old standalone box; positioned relative so the
   dismiss × can sit in its corner. */
.plan-spare { position: relative; margin: 6px 0 8px; }
.spare-line { margin: 0; padding: 13px 16px; border: 1px solid var(--line); border-left: 4px solid var(--blue); border-radius: 12px; background: var(--paper); font-size: 0.98rem; line-height: 1.4; color: var(--ink); }
.plan-spare .spare-line { padding-right: 36px; }
.spare-line b { color: var(--blue); }
.spare-count { display: inline-block; margin-left: 4px; font-size: 0.82rem; font-weight: 700; color: var(--red-dark); white-space: nowrap; }
.spare-jump { cursor: pointer; text-decoration: underline; }
.spare-jump:hover { color: var(--red); }
.spare-jump:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; border-radius: 6px; }
/* Dismiss × for the spare prompt, sized for the corner. */
.plan-spare-x { position: absolute; top: 6px; right: 8px; width: 24px; height: 24px; display: grid; place-items: center; border: none; background: transparent; color: var(--muted); font-size: 1.2rem; line-height: 1; cursor: pointer; border-radius: 6px; }
.plan-spare-x:hover { color: var(--ink); background: rgba(0, 0, 0, 0.05); }
.plan-spare-x:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }

/* Hairline between the top actionable card (plan, or the CTA before one
   exists) and the browse section (shows title, filters, map, list). */
.section-divider { border: 0; height: 1px; background: var(--line); margin: 28px 0 4px; }

/* --- Map / list view switch: one view at a time, flipped from a right rail --- */
.view-area { display: flex; align-items: stretch; gap: 10px; margin-top: 20px; }
.view-panes { flex: 1 1 auto; min-width: 0; }
/* Inside the flex row the panes own no top margin — .view-area supplies it. */
.view-panes > .map-section,
.view-panes > .shows-section { margin-top: 0; }
/* The rail: a slim column pinned to the right, sticky so it stays reachable
   while a long list scrolls. */
.view-switch {
  flex: 0 0 auto; align-self: flex-start;
  position: sticky; top: 12px;
  display: flex; flex-direction: column; gap: 6px;
  padding: 5px; border: 1px solid var(--line); border-radius: 14px; background: var(--paper);
}
.view-btn {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  width: 52px; padding: 9px 4px;
  font: inherit; font-size: 0.68rem; font-weight: 700; letter-spacing: 0.01em;
  color: var(--muted); background: transparent; border: none; border-radius: 10px;
  cursor: pointer; transition: color 0.12s ease, background 0.12s ease;
}
.view-btn.is-active { color: #fff; background: var(--red); }
.view-btn:not(.is-active):hover { color: var(--ink); background: rgba(0, 0, 0, 0.04); }
.view-btn:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
.view-btn-label { line-height: 1; }

/* --- Map: supporting, calm, modest --- */
.map-section { margin: 20px 0 0; }
#leaflet-map { height: 260px; border: 1px solid var(--line); border-radius: 14px; box-shadow: none; }
/* Desaturate the tiles a touch so the map reads as informative, not the main thing. */

