    '| map hidden:', (await p.getAttribute('#map','hidden')) !== null,
    '| list hidden:', (await p.getAttribute('#shows','hidden')) !== null,
    '| pressed:', await p.$$eval('.view-btn', b => b.filter(x=>x.getAttribute('aria-pressed')==='true').map(x=>x.dataset.mode)));
  if (mode !== 'map') console.log('   top rows:', await rows());
  await p.screenshot({ path: `mode-${mode}.png`, clip: await clip() });
}
await b.close();
